fn contains(self, x: i64, y: i64) -> bool {
    x >= self.x && x < self.x + self.w && y >= self.y && y < self.y + self.h
fn border_width(&self) -> i64 {
    self.cw + self.frame(true)
}
fn border_height(&self) -> i64 {
    self.ch + self.frame(false)
}
fn border(&self) -> Rect {
    Rect {
        x: self.x,
        y: self.y,
        w: self.border_width(),
        h: self.border_height(),
    }
}
fn content(&self) -> Rect {
    Rect {
        x: self.x + self.edge("border", 3) + self.edge("padding", 3),
        y: self.y + self.edge("border", 0) + self.edge("padding", 0),
        w: self.cw,
        h: self.ch,
    }
fn layout(
    &mut self,
    e: usize,
    cw_ref: i64,
    ch_ref: Option<i64>,
    fw: Option<i64>,
    given_height: Option<i64>,
) -> i64 {
    self.elements[e].cw = cw;
    self.elements[e].ch = fh.unwrap_or_else(|| self.elements[e].clamp(a, ch_ref, false));
        self.elements[i].x = bx + self.elements[i].rx + dx;
        self.elements[i].y = by + self.elements[i].ry + dy;
        "HIT" => {
            let x: i64 = a[1].parse().unwrap();
            let y: i64 = a[2].parse().unwrap();
            if x >= self.width || y >= self.height {
                return vec![format!("error: point {} {} outside viewport", x, y)];
            }
            let mut at = (0..self.elements.len()).rev().find(|i| {
                self.elements[*i].displayed && self.elements[*i].border().contains(x, y)
            });
            let mut path = Vec::new();
            while let Some(i) = at {
                path.push(self.elements[i].id.clone());
                at = self.elements[i].parent;
            }
            path.reverse();
            vec![format!(
                "hit {} {}: {}",
                x,
                y,
                if path.is_empty() {
                    "none".to_string()
                } else {
                    path.join(" > ")
                }
            )]
    elements.push(e);
